    {
      "@id": "activity:translation-story_text_1-2026-07-08T06:55:04.160194+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T06:55:04.160194+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_1",
      "@type": "prov:Entity",
      "prov:value": "Aristotle walked as he taught. He believed the act of moving — through space, through questions, through observation — was itself a form of thinking. Two thousand years later, the research agrees."
    },
    {
      "@id": "entity:target-story_text_1-v1",
      "@type": "prov:Entity",
      "prov:value": "Aristote marchait tout en enseignant. Il croyait que l'acte de se déplacer - dans l'espace, à travers les questions, par l'observation - était en soi une forme de pensée. Deux mille ans plus tard, la recherche est d'accord.",
      "generated_by": {
        "@id": "activity:translation-story_text_1-2026-07-08T06:55:04.160194+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_1"
      }
    },
    {
      "@id": "activity:translation-story_text_2-2026-07-08T06:55:04.160194+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T06:55:04.160194+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_2",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware puts that insight in your pocket. Teachers design activities that bring curriculum to life in the real world. Students explore, capture, and reflect. Peri guides the inquiry. And learning — finally — moves."
    },
    {
      "@id": "entity:target-story_text_2-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware met cette connaissance dans votre poche. Les enseignants conçoivent des activités qui donnent vie au programme dans le monde réel. Les étudiants explorent, capturent et réfléchissent. Peri guide l'enquête. Et enfin, l'apprentissage se déplace.",
      "generated_by": {
        "@id": "activity:translation-story_text_2-2026-07-08T06:55:04.160194+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_2"
      }
    },
