    {
      "@id": "activity:translation-field_journal_desc-2026-07-08T07:53:56.538824+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T07:53:56.538824+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-field_journal_desc",
      "@type": "prov:Entity",
      "prov:value": "Students don't just do an activity — they record it. The Field Journal is where raw observations become structured knowledge. Back at their desk, students expand their notes with extended analysis, personal reflection, and connections to what they already know. Teachers can review, respond, and promote entries to the student's permanent portfolio."
    },
    {
      "@id": "entity:target-field_journal_desc-v1",
      "@type": "prov:Entity",
      "prov:value": "Les étudiants ne se contentent pas de faire une activité — ils la consignent. Le Field Journal est l'endroit où les observations brutes deviennent des connaissances structurées. De retour à leur bureau, les étudiants développent leurs notes avec une analyse approfondie, une réflexion personnelle et des liens avec ce qu'ils savent déjà. Les enseignants peuvent consulter, répondre et promouvoir des entrées dans le portefeuille permanent de l'étudiant.",
      "generated_by": {
        "@id": "activity:translation-field_journal_desc-2026-07-08T07:53:56.538824+00:00"
      },
      "used_source": {
        "@id": "entity:source-field_journal_desc"
      }
