    {
      "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-08T08:01:29.378301+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T08:01:29.378301+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr",
      "@type": "prov:Entity",
      "prov:value": "When you upload a PDF or CSV, Ollama extracts the criteria once and caches them. Re-uploading the same file skips Ollama entirely (checksum match). A different file triggers re-extraction. Pre-seeded state sets were hand-authored and are always instant. Sets expire annually — you'll see a warning near the expiry date."
    },
    {
      "@id": "entity:target-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-v1",
      "@type": "prov:Entity",
      "prov:value": "Lors du téléchargement d'un PDF ou CSV, Ollama extrait les critères une seule fois et les met en cache. Le rechargement du même fichier saute Ollama entièrement (coincidence de la somme de contrôle). Un fichier différent déclenche une nouvelle extraction. Les ensembles d'états pré-initialisés ont été élaborés à la main et sont toujours instantanés. Les ensembles expirent annuellement - vous verrez un avertissement proche de la date d'expiration.",
      "generated_by": {
        "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-08T08:01:29.378301+00:00"
      },
      "used_source": {
        "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr"
      }
    },
