    {
      "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware began as a white paper written inside McGraw-Hill Education. It argued that GPS-enabled mobile devices would transform learning — that students walking through real places, guided by structured inquiry, could learn in a way textbooks never allowed."
    },
    {
      "@id": "entity:target-components_landingpage.peripateticware_began_as_a_white_paper_w-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware a commencé sous la forme d'un document blanc écrit au sein de McGraw-Hill Education. Il soutenait que les appareils mobiles équipés de GPS transformeraient l'apprentissage - que les étudiants marchant dans des lieux réels, guidés par une enquête structurée, pourraient apprendre d'une manière que les manuels scolaires n'ont jamais permis.",
      "generated_by": {
        "@id": "activity:translation-components_landingpage.peripateticware_began_as_a_white_paper_w-2026-07-08T08:01:52.489076+00:00"
      },
      "used_source": {
        "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w"
      }
    },
