    {
      "@id": "activity:translation-team_1_bio-2026-07-08T08:09:54.743545+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T08:09:54.743545+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-team_1_bio",
      "@type": "prov:Entity",
      "prov:value": "Paul spent a decade as a teacher, four years working for edtechs, and has been experimenting with how to break learning out of books and classrooms for two decades. Peripateticware takes advantage of LLM advancements and leverages mobile technologies to allow students to learn from the world with guidance from their teachers wherever they choose to roam."
    },
    {
      "@id": "entity:target-team_1_bio-v1",
      "@type": "prov:Entity",
      "prov:value": "Paul a passé une décennie en tant qu'enseignant, quatre ans à travailler pour des edtechs et expérimenté depuis deux décennies comment sortir de l'apprentissage des livres et des salles de classe. Peripateticware profite des avancées en matière de modèles de langage et utilise les technologies mobiles pour permettre aux étudiants d'apprendre du monde entier avec le soutien de leurs enseignants, où qu'ils choisissent d'aller.",
      "generated_by": {
        "@id": "activity:translation-team_1_bio-2026-07-08T08:09:54.743545+00:00"
      },
      "used_source": {
        "@id": "entity:source-team_1_bio"
      }
    },
